    coords: [64.4147, 39.7758],
    name: { de: "Poi-Kalyan", hu: "Po-i-Kalján", ro: "Po-i-Kalyan", en: "Po-i-Kalyan"},
    image: "/poi-images/po-i-kalyan-bukhara-history-v2.webp",
    description: { de: "Ein architektonischer Komplex im Zentrum von Buchara, berühmt für sein beeindruckendes Minarett, das sogar Dschingis Khan verschonte.", hu: "Egy építészeti komplexum Buhara központjában, híres lenyűgöző minaretjéről, amelyet még Dzsingisz kán is megkímélt.", ro: "Un complex arhitectural în centrul orașului Bukhara, faimos pentru minaretul său impresionant, cruțat chiar și de Ginghis Han.", en: "An architectural complex in the center of Bukhara, famous for its impressive minaret that even Genghis Khan spared." , es: "Un complejo arquitectónico en el centro de Bujará, famoso por su impresionante minarete que incluso Gengis Kan perdonó.", pt: "Um complexo arquitetónico no centro de Bucara, famoso pelo seu impressionante minarete que até Gengis Khan poupou.", fr: "Un complexe architectural au centre de Boukhara, célèbre pour son minaret impressionnant que même Gengis Khan a épargné."},
    facts: {
      de: ["Kalyan-Minarett ist 45 Meter hoch", "Erbaut im Jahr 1127", "Das Zentrum des islamischen Buchara"],
      hu: ["A Kalján-minaret 45 méter magas", "1127-ben épült", "Az iszlám Buhara központja"],
      ro: ["Minaretul Kalyan are 45 de metri înălțime", "Construit în anul 1127", "Centrul Bukharei islamice"],
      en: ["Kalyan Minaret is 45 meters high", "Built in the year 1127", "The center of Islamic Bukhara"],
      es: ["El minarete Kalyan mide 45 metros de altura", "Construido en el año 1127", "El centro de la Bujará islámica"],
      pt: ["O Minarete Kalyan tem 45 metros de altura", "Construído no ano de 1127", "O centro da Bucara islâmica"],
      fr: ["Le minaret Kalyan mesure 45 mètres de haut", "Construit en l'an 1127", "Le centre de la Boukhara islamique"],
    }, image: "/poi-images/po-i-kalyan-bukhara-history-v2.webp",
    descriptionAdvanced: {
      de: "Po-i-Kalyan ist ein religiöser Komplex in Buchara, Usbekistan, bestehend aus der Kalyan-Moschee, dem Kalyan-Minarett und der Mir-i-Arab-Medresse. Das Kalyan-Minarett wurde 1127 von Arslan Khan erbaut und ist 46,5 Meter hoch. Es diente als Aussichtsturm und als Leuchtturm für Karawanen. Die Kalyan-Moschee wurde im 15. Jahrhundert errichtet und fasst bis zu 12.000 Gläubige. Die Mir-i-Arab-Medresse wurde 1535–1536 unter dem Scheibaniden-Herrscher Ubaydullah Khan gebaut. Der gesamte Komplex ist ein Meisterwerk der islamischen Architektur und steht seit 1993 auf der UNESCO-Welterbeliste. Die Bauweise verwendet gebrannte Ziegel und Majolika-Fliesen. Die Kuppel der Moschee hat einen Durchmesser von 18 Metern. Der Komplex wurde im 20. Jahrhundert renoviert und ist heute ein wichtiges Zentrum des islamischen Lernens.",
      hu: "A Po-i-Kalyan egy épületegyüttes Buharában, Üzbegisztánban, amely a Kalyan minaretből, a Kalyan mecsetből és a Mir-i-Arab medreszéből áll. A Kalyan minaret 1127-ben épült, magassága 46,5 méter, és a város egyik jelképe. A mecset a 15. században épült, és lenyűgöző méretű: udvara 39x39 méteres. A Mir-i-Arab medresze 1535–1536 között épült, és ma is működő teológiai iskola, ahol diákok tanulják a Koránt és az iszlám jogot. Az együttes a buharai építészet csúcspontját képviseli, kék csempékkel és geometrikus mintákkal díszítve. A komplexum a történelem során többször súlyosan megrongálódott, de a 20. században restaurálták. A mecsetben egy hatalmas, 18 méter átmérőjű kupola található. Az együttes ma turisztikai látványosság és vallási hely.",
      ro: "Po-i-Kalyan este un ansamblu arhitectural din Bukhara, Uzbekistan, care include Moscheea Kalyan, Minaretul Kalyan și Madrasa Mir-i-Arab. Minaretul Kalyan a fost construit în 1127 de către Arslan Khan și are o înălțime de 46,5 metri. A fost folosit ca far pentru caravane și ca turn de veghe. Moscheea Kalyan a fost construită în secolul al XV-lea și poate găzdui până la 12.000 de credincioși. Madrasa Mir-i-Arab a fost fondată în 1535–1536 și este una dintre cele mai prestigioase instituții de învățământ islamice din Asia Centrală. Ansamblul face parte din Patrimoniul Mondial UNESCO din 1993. Arhitectura se remarcă prin utilizarea cărămizii arse și a faianței glazurate. Domul moscheii are un diametru de 18 metri. Ansamblul a suferit renovări majore în perioada sovietică.",
      en: "Po-i-Kalyan is a prominent architectural complex in Bukhara, Uzbekistan, centered around the Kalyan Minaret. The minaret, built in 1127 by the Karakhanid ruler Arslan Khan, stands 46.5 meters tall and is known as the 'Tower of Death' because criminals were once thrown from its top. The adjacent Kalyan Mosque, completed in 1514, has a courtyard measuring 39 by 39 meters and a large iwan. The Mir-i-Arab Madrasa, built between 1535 and 1536, remains a functioning madrasa. The complex is a UNESCO World Heritage Site as part of the Historic Centre of Bukhara. The minaret's foundation is 9 meters deep, and its diameter tapers from 9 meters at the base to 6 meters at the top. The mosque can accommodate 12,000 worshippers during major prayers.",
      es: "Po-i-Kalyan es un complejo religioso en Bujará, Uzbekistán, compuesto por la mezquita Kalyan, el minarete Kalyan y la madraza Mir-i-Arab. El minarete Kalyan fue construido en 1127 por Arslan Khan y mide 46,5 metros de altura. Sirvió como torre de vigilancia y como faro para las caravanas. La mezquita Kalyan fue erigida en el siglo XV y tiene capacidad para 12.000 fieles. La madraza Mir-i-Arab se construyó entre 1535 y 1536 bajo el mandato del gobernante shaybánida Ubaydullah Khan. Todo el complejo es una obra maestra de la arquitectura islámica y forma parte de la lista del Patrimonio Mundial de la UNESCO desde 1993. La construcción utiliza ladrillos cocidos y azulejos de majólica. La cúpula de la mezquita tiene un diámetro de 18 metros. El complejo fue renovado en el siglo XX y es hoy un importante centro de enseñanza islámica.",
      pt: "Po-i-Kalyan é um complexo religioso em Bucara, Uzbequistão, composto pela Mesquita Kalyan, o Minarete Kalyan e a Madraça Mir-i-Arab. O Minarete Kalyan foi construído em 1127 por Arslan Khan e tem 46,5 metros de altura. Serviu como torre de vigia e como farol para as caravanas. A Mesquita Kalyan foi erguida no século XV e comporta até 12.000 fiéis. A Madraça Mir-i-Arab foi construída entre 1535-1536 sob o governo do soberano xibânida Ubaydullah Khan. Todo o complexo é uma obra-prima da arquitetura islâmica e está na lista do Património Mundial da UNESCO desde 1993. A construção utiliza tijolos cozidos e azulejos de majólica. A cúpula da mesquita tem um diâmetro de 18 metros. O complexo foi renovado no século XX e é hoje um importante centro de aprendizagem islâmica.",
      fr: "Po-i-Kalyan est un complexe religieux à Boukhara, en Ouzbékistan, comprenant la mosquée Kalyan, le minaret Kalyan et la médersa Mir-i-Arab. Le minaret Kalyan a été construit en 1127 par Arslan Khan et s'élève à 46,5 mètres. Il servait de tour d'observation et de phare pour les caravanes. La mosquée Kalyan a été érigée au XVe siècle et peut accueillir jusqu'à 12 000 fidèles. La médersa Mir-i-Arab fut bâtie en 1535-1536 sous le règne du souverain chaybanide Ubaydullah Khan. L'ensemble du complexe est un chef-d'œuvre de l'architecture islamique et figure sur la liste du patrimoine mondial de l'UNESCO depuis 1993. La maçonnerie utilise des briques cuites et des carreaux de majolique. Le dôme de la mosquée possède un diamètre de 18 mètres. Rénové au XXe siècle, le complexe demeure un centre d'enseignement islamique de premier plan.",
    },
