    description: { de: "Eine beeindruckende Moschee in Shahrisabz mit einer massiven blauen Kuppel, die von Ulugh Beg erbaut wurde.", hu: "Látványos mecset Shahrisabzban, masszív kék kupolával, amelyet Ulugbek építtetett.", ro: "O moschee impresionantă în Shahrisabz, cu o cupolă albastră masivă, construită de Ulugh Beg.", en: "An impressive mosque in Shahrisabz with a massive blue dome, built by Ulugh Beg." , es: "Una impresionante mezquita en Shahrisabz con una enorme cúpula azul, construida por Ulugh Beg.", pt: "Uma impressionante mesquita em Shahrisabz com uma enorme cúpula azul, construída por Ulugh Beg.", fr: "Une mosquée impressionnante à Shahrisabz dotée d'une immense coupole bleue, construite par Ulugh Beg."},
