      en: ["The mosque was built in 1435 by the astronomer Ulugh Beg.", "The name Kok Gumbaz translates from Persian as 'Blue Dome.'", "The dome's outer diameter measures approximately 46 meters.", "It is the main building of the Dorut Tilyovat memorial complex.", "Arabic inscriptions on the dome praise God and the Prophet Muhammad.", "The structure underwent significant restoration in the 1990s."],
      es: ["La cúpula tiene un diámetro de 30 metros.", "La mezquita fue construida en 1437.", "El pishtaq tiene 22 metros de altura.", "La mezquita tiene capacidad para unos 2.000 fieles.", "Forma parte del Patrimonio Mundial de Shahrisabz (2000).", "Los minaretes tienen 30 metros de altura."],
