      fr: ["La coupole a un diamètre de 30 mètres.", "La mosquée a été construite en 1437.", "Le pishtaq mesure 22 mètres de haut.", "La mosquée accueille environ 2 000 fidèles.", "Inscrite au patrimoine mondial de Shahrisabz (2000).", "Les minarets mesurent 30 mètres de haut."],
